// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(uint128 amount1, uint128 amount2, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount1 > 0);
        uint256 v1 = bound(uint256(amount1), 1, type(uint128).max);
        uint256 v2 = bound(uint256(amount2), 0, type(uint128).max - v1);

        vm.deal(actor, v1 + v2);
        vm.prank(actor);
        c.Put{value: v1}(0);
        vm.prank(actor);
        c.Put{value: v2}(0);

        (, uint256 balance) = c.Acc(actor);
        assertTrue(balance == v1 + v2);
    }
}
